const robbioState={lesson:0,photo:0,point:0,cycle:0};
function robbioPhotoHtml(){
 const p=robbioPhotos[robbioState.photo];
 return `<div class="robbio-photo"><img src="assets/frio-robbio/${p.file}" alt="${esc(p.title)}" loading="lazy">${p.points.map((x,i)=>`<button class="robbio-pin ${i===robbioState.point?'selected':''}" style="left:${x[1]}%;top:${x[2]}%" data-robbio-point="${i}" aria-label="${i+1}. ${esc(x[0])}" aria-pressed="${i===robbioState.point}">${i+1}</button>`).join('')}</div><h3>${esc(p.title)}</h3><p class="robbio-caption">${esc(p.note)}</p><div class="robbio-point-buttons">${p.points.map((x,i)=>`<button class="secondary" data-robbio-point="${i}" aria-pressed="${i===robbioState.point}">${i+1}. ${esc(x[0])}</button>`).join('')}</div><div id="robbio-point-info" class="robbio-note" aria-live="polite"><strong>${esc(p.points[robbioState.point][0])}</strong><p>${esc(p.points[robbioState.point][3])}</p></div><a href="https://drive.google.com/file/d/${p.id}/view" target="_blank" rel="noopener">Abrir foto original ↗</a>`;
}
function robbioBindPhoto(){
 document.querySelectorAll('[data-robbio-point]').forEach(b=>b.onclick=()=>{
  robbioState.point=Number(b.dataset.robbioPoint);const p=robbioPhotos[robbioState.photo].points[robbioState.point];
  document.querySelector('#robbio-point-info').innerHTML=`<strong>${esc(p[0])}</strong><p>${esc(p[3])}</p>`;
  document.querySelectorAll('[data-robbio-point]').forEach(x=>{const active=Number(x.dataset.robbioPoint)===robbioState.point;x.setAttribute('aria-pressed',String(active));x.classList.toggle('selected',active)});
 });
}
function renderFrioWorkshop(){
 const lesson=robbioLessons[robbioState.lesson];
 if(!lesson.photos.includes(robbioState.photo)){robbioState.photo=lesson.photos[0];robbioState.point=0}
 document.querySelector('footer').textContent='Taller de Robbio · Primeros materiales. Las identificaciones pendientes requieren placa, esquema o trazado de conexiones.';
 app.innerHTML=`<section class="robbio-hero"><span class="pending-badge">EN DESARROLLO · PROF. ROBBIO</span><h1>Del equipo real<br>al circuito frigorífico.</h1><p class="lead">Taller: Sistemas de control y Frío</p><p>Reconocé las piezas, seguí el refrigerante y explicá qué hace cada control.</p><div class="robbio-meta"><span>5 recorridos de estudio</span><span>8 fotos comentadas · incluye las 3 nuevas</span><a href="${robbioFolder}" target="_blank" rel="noopener">Todos los materiales ↗</a></div></section>
 <nav class="robbio-tabs" aria-label="Temas del taller">${robbioLessons.map((l,i)=>`<button class="secondary" data-robbio-lesson="${i}" aria-pressed="${i===robbioState.lesson}">${l.title}</button>`).join('')}</nav>
 <section class="robbio-section"><div class="section-head"><div><span class="eyebrow">${String(robbioState.lesson+1).padStart(2,'0')} / OBSERVAR · RELACIONAR · EXPLICAR</span><h2>${lesson.title}</h2><p>${lesson.intro}</p></div></div><div class="robbio-columns"><article class="robbio-visual"><label for="robbio-photo-select">Elegir foto del taller</label><select id="robbio-photo-select">${lesson.photos.map(i=>`<option value="${i}" ${i===robbioState.photo?'selected':''}>${esc(robbioPhotos[i].title)}</option>`).join('')}</select><div id="robbio-photo-panel">${robbioPhotoHtml()}</div></article><div class="robbio-steps">${lesson.steps.map((s,i)=>`<article><span class="robbio-step-number">${i+1}</span><div><h3>${esc(s[0])}</h3><p>${esc(s[1])}</p></div></article>`).join('')}<p class="robbio-caption">Referencia: ${esc(lesson.ref)} <a href="${robbioManual}" target="_blank" rel="noopener">Abrir manual ↗</a></p></div></div></section>
 <section class="robbio-cycle"><span class="eyebrow">ESQUEMA CONCEPTUAL · MODO FRÍO</span><h2>Un refrigerante. Cuatro transformaciones.</h2><p>Elegí una etapa. Las flechas indican el recorrido del ciclo básico; no representan el trazado exacto del banco del taller.</p><img class="robbio-cycle-diagram" src="assets/frio-robbio/ciclo.svg" alt="Ciclo cerrado: compresor, condensador, expansión, evaporador y retorno por aspiración. Estados del refrigerante y calor intercambiado con el aire."><div class="robbio-cycle-buttons">${robbioCycle.map((c,i)=>`<button data-robbio-cycle="${i}" aria-pressed="${i===robbioState.cycle}"><small>0${i+1}</small>${c.name}<span aria-hidden="true"> →</span></button>`).join('')}<span class="robbio-return">↳ Aspiración: vuelve al compresor</span></div><div id="robbio-cycle-detail" aria-live="polite"></div></section>
 <section class="robbio-practice"><span class="eyebrow">PRACTICAR LA EXPLICACIÓN · SIN NOTA</span><h2>Decilo sin saltear pasos.</h2><p>Respondé en voz alta antes de abrir la guía. Incluí ubicación, función, recorrido, estado del refrigerante y relación con el control cuando corresponda.</p>${lesson.questions.map(q=>`<details><summary>${esc(q[0])}</summary><p>${esc(q[1])}</p></details>`).join('')}</section>
 <section class="robbio-sources"><h2>Materiales y alcance.</h2><p>Fotos de clase aportadas por ustedes y explicación basada en el manual. Las piezas dudosas están marcadas como pendientes; las fotos no permiten reconstruir por completo el cableado ni todas las tuberías.</p><div class="robbio-source-grid"><a href="${robbioFolder}" target="_blank" rel="noopener">Carpeta del taller · 26 imágenes y 2 videos ↗</a><a href="${robbioManual}" target="_blank" rel="noopener">Manual de Refrigeración · Lijó ↗</a><a href="https://drive.google.com/file/d/11eOLh2icIEO5PJqTYEw190kcCodlGkOl/view" target="_blank" rel="noopener">Válvulas de expansión · documentación ↗</a><a href="https://drive.google.com/file/d/1Pq9cDXiYLA5aMU4nFHYO25kOWttHjOnP/view" target="_blank" rel="noopener">Danfoss Maneurop NTZ · familia específica, no ficha del Toshiba ↗</a><a href="https://assets.danfoss.com/documents/latest/50825/AX266348279899en-000101.pdf" target="_blank" rel="noopener">Danfoss · instalación de válvulas termostáticas ↗</a></div><p class="robbio-caption">Los videos quedan disponibles en la carpeta como material original; no se usaron para confirmar maniobras. Taller en desarrollo: todavía sin examen automático propio.</p></section>`;
 document.querySelectorAll('[data-robbio-lesson]').forEach(b=>b.onclick=()=>{robbioState.lesson=Number(b.dataset.robbioLesson);renderFrioWorkshop();document.querySelector(`[data-robbio-lesson="${robbioState.lesson}"]`).focus({preventScroll:true})});
 document.querySelector('#robbio-photo-select').onchange=e=>{robbioState.photo=Number(e.target.value);robbioState.point=0;document.querySelector('#robbio-photo-panel').innerHTML=robbioPhotoHtml();robbioBindPhoto()};
 document.querySelectorAll('[data-robbio-cycle]').forEach(b=>b.onclick=()=>{robbioState.cycle=Number(b.dataset.robbioCycle);robbioRenderCycle()});
 robbioBindPhoto();robbioRenderCycle();
}
function robbioRenderCycle(){const c=robbioCycle[robbioState.cycle];document.querySelector('#robbio-cycle-detail').innerHTML=`<div><span class="eyebrow">REFRIGERANTE</span><h3>${c.state}</h3><p>${c.text}</p></div><div><span class="eyebrow">AIRE Y ENERGÍA</span><p>${c.air}</p></div>`;document.querySelectorAll('[data-robbio-cycle]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.robbioCycle)===robbioState.cycle)))}
